/* From Uiverse.io by AqFox - Tags: button */
.__UIV_SCOPE__ .custom-btn {
  width: 130px;
  height: 40px;
  color: #fff;
  border-radius: 5px;
  padding: 10px 25px;
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  background: transparent;
  cursor: pointer;
  transition: all 0.3s ease;
  position: relative;
  display: inline-block;
  box-shadow: inset 2px 2px 2px 0px rgba(255,255,255,.5),
   7px 7px 20px 0px rgba(0,0,0,.1),
   4px 4px 5px 0px rgba(0,0,0,.1);
  outline: none;
  font-size: 15px;
}

.__UIV_SCOPE__ .btn-4 {
  background-color: #004dff;
  background-image: linear-gradient(315deg, #03c8a8 0%, #004dff 74%);
  line-height: 42px;
  padding: 0;
  border: none;
}

.__UIV_SCOPE__ .btn-4:hover {
  background-color: #004dff;
  background-image: linear-gradient(315deg, #004dff 0%, #03c8a8 74%);
}

.__UIV_SCOPE__ .btn-4 span {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ .btn-4:before,
.__UIV_SCOPE__ .btn-4:after {
  position: absolute;
  content: "";
  right: 0;
  top: 0;
  box-shadow: 4px 4px 6px 0 rgba(255,255,255,.9),
              -4px -4px 6px 0 rgba(116, 125, 136, .2), 
    inset -4px -4px 6px 0 rgba(255,255,255,.9),
    inset 4px 4px 6px 0 rgba(116, 125, 136, .3);
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .btn-4:before {
  height: 0%;
  width: .1px;
}

.__UIV_SCOPE__ .btn-4:after {
  width: 0%;
  height: .1px;
}

.__UIV_SCOPE__ .btn-4:hover:before {
  height: 100%;
}

.__UIV_SCOPE__ .btn-4:hover:after {
  width: 100%;
}

.__UIV_SCOPE__ .btn-4 span:before,
.__UIV_SCOPE__ .btn-4 span:after {
  position: absolute;
  content: "";
  left: 0;
  bottom: 0;
  box-shadow: 4px 4px 6px 0 rgba(255,255,255,.9),
              -4px -4px 6px 0 rgba(116, 125, 136, .2), 
    inset -4px -4px 6px 0 rgba(255,255,255,.9),
    inset 4px 4px 6px 0 rgba(116, 125, 136, .3);
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .btn-4 span:before {
  width: .1px;
  height: 0%;
}

.__UIV_SCOPE__ .btn-4 span:after {
  width: 0%;
  height: .1px;
}

.__UIV_SCOPE__ .btn-4 span:hover:before {
  height: 100%;
}

.__UIV_SCOPE__ .btn-4 span:hover:after {
  width: 100%;
}
